def test_count_results():
    results = [True, True, False, True, False, False, True]
    passed, failed = count_results(results)
    assert passed == 4, f"ожидалось 4 успешных, получено {passed}"
    assert failed == 3, f"ожидалось 3 провальных, получено {failed}"


def test_format_summary():
    results = [True, True, False, True, False, False, True]
    assert format_summary(results) == "Passed: 4, Failed: 3", "сообщение должно точно соответствовать формату 'Passed: N, Failed: M'"


def test_last_three():
    results = [True, True, False, True, False, False, True]
    assert last_three(results) == [False, False, True], "срез должен содержать последние три элемента списка в исходном порядке"


def test_last_three_short_list():
    assert last_three([True, False]) == [True, False], "если элементов меньше трёх, срез должен вернуть весь список"
